'use strict';
const Hardware = window.HARDWARE || [];
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = {get(){try{return JSON.parse(localStorage.getItem('atl-saved')||'[]').filter(id=>Hardware.some(d=>d.id===id));}catch{return[];}},set(v){try{localStorage.setItem('atl-saved',JSON.stringify(v));return true;}catch{return false;}}};
function toast(message){const el=document.querySelector('.toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
function imageMarkup(d, cls=''){return `<img ${cls?`class="${cls}"`:''} src="${escapeHTML(d.image)}" alt="${escapeHTML(d.imageTitle)}" loading="lazy" decoding="async">`;}
function card(d){const saved=storage.get().includes(d.id);return `<article class="hardware-card"><a class="card-image-link" href="story.html?id=${d.id}" aria-label="Read the story of ${escapeHTML(d.name)}">${imageMarkup(d)}<span class="card-number">${d.body.toUpperCase()} / ${String(d.index).padStart(2,'0')}</span></a><button class="save-button" data-save="${d.id}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} ${escapeHTML(d.name)}">${saved?'♥':'♡'}</button><div class="card-body"><p class="card-category">${escapeHTML(d.category)}</p><h3><a href="story.html?id=${d.id}">${escapeHTML(d.name)}</a></h3><p class="card-meta"><span>${escapeHTML(d.mission)}</span><span>${escapeHTML(d.year)}</span></p><p class="card-purpose">${escapeHTML(d.purpose)}</p><p class="card-caption">Image: ${escapeHTML(d.displayCaption||d.imageTitle)}${d.imageContext?' · Mission context':''}</p></div><div class="card-bottom"><span class="status-tag ${d.operating?'operating':''}">${d.operating?'Ongoing science / catalog active':'Retired / remains'}</span><a class="story-link" href="story.html?id=${d.id}">Read the story ↗</a></div><details class="exhibit-details"><summary>Explore the science</summary><dl><div><dt>Scientific contribution</dt><dd>${escapeHTML(d.contribution)}</dd></div><div><dt>Why it matters</dt><dd>${escapeHTML(d.matters)}</dd></div><div><dt>Current status</dt><dd>${escapeHTML(d.status)}</dd></div></dl></details></article>`;}
document.querySelectorAll('nav [data-page]').forEach(a=>{if(a.dataset.page===document.body.dataset.page)a.setAttribute('aria-current','page');});
document.addEventListener('click',e=>{const button=e.target.closest('[data-save]');if(!button)return;let list=storage.get();const id=button.dataset.save;const had=list.includes(id);list=had?list.filter(x=>x!==id):[...list,id];if(!storage.set(list)){toast('Saving is unavailable in this browser.');return;}document.querySelectorAll(`[data-save="${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',String(!had));const d=Hardware.find(x=>x.id===id);b.setAttribute('aria-label',`${had?'Save':'Unsave'} ${d.name}`);b.textContent=b.classList.contains('save-button')?had?'♡':'♥':had?'♡ Save this story':'♥ Story saved';});toast(had?'Story removed from your collection':'Story saved for your next expedition');document.dispatchEvent(new Event('savedchange'));});
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const img=e.target;img.classList.add('image-failure');if(img.dataset.failed)return;img.dataset.failed='true';img.src='assets/favicon.svg';img.alt='Image unavailable. Open the linked NASA image record for the original.';},true);
